const D=n=>Date.now()+n*DAY,fd=d=>new Date(d).toLocaleDateString('fr-FR'),ft=d=>new Date(d).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
