const MD=d=>{const x=mt(d),pub=(d.hist||[]).find(e=>e.t==='PUBLISH'),it=(l,v)=>`<div><span class="mut">${l}</span><b>${v}</b></div>`;
 return `<div class="card"><h2>Métadonnées</h2><div class="meta">${it('Code',esc(d.code))}${it('Type de document',esc(d.tp||'—'))}${it('Service',SV[d.svc])}${it('Propriétaire',esc(un(x.own)))}${it('Auteur',esc(un(d.author)))}${it('Confidentialité',esc(x.conf))}${it('Mots-clés',x.kw?esc(x.kw):'—')}${it('Créé le',fd(d.versions[0].at))}${it('Émis le',pub?fd(pub.at):'—')}${it('Version en vigueur','v'+lv(d).n)}${it("Valide jusqu'au",d.valid?fd(d.valid):'—')}</div></div>`};
const VH=d=>`<div class="card sc"><h2>Versions et nature des changements</h2><table class="rt"><thead><tr><th>Version</th><th>Date</th><th>Auteur</th><th>Nature des changements</th><th>Empreinte</th></tr></thead><tbody>${[...d.versions].reverse().map(x=>`<tr><td data-l="Version"><b>v${x.n}</b></td><td data-l="Date">${ft(x.at)}</td><td data-l="Auteur">${x.by?esc(un(x.by)):'—'}</td><td data-l="Nature">${x.note?esc(x.note):'—'}</td><td data-l="Empreinte"><code>${x.hash.slice(0,10)}…</code></td></tr>`).join('')}</tbody></table></div>`;
