function kpis(){const P=S.docs.filter(d=>d.status==='PUBLIE'),lateL=[];let att=0,sg=0;
 P.forEach(d=>{const v=lv(d);U.filter(u=>u.svc===d.svc).forEach(u=>{att++;if(d.sigs.some(s=>s.u===u.id&&s.v===v.n))sg++;else if(v.at<D(-7))lateL.push([d,u])})});
 const ds=[];let sub=0,rej=0;S.docs.forEach(d=>{let s=null;(d.hist||[]).forEach(e=>{if(e.t==='SUBMIT'){s=e.at;sub++}else if(e.t==='REJECT'){s=null;rej++}else if(e.t==='PUBLISH'&&s){ds.push((e.at-s)/DAY);s=null}})});
 return{n:S.docs.length,pub:P.length,att,sg,late:lateL.length,lateDocs:new Set(lateL.map(x=>x[0].code)).size,lateL,avg:ds.length?ds.reduce((a,b)=>a+b,0)/ds.length:null,sub,rej,exp:P.filter(d=>d.valid&&d.valid<D(30)).length,evd:S.docs.filter(d=>(d.proofs||[]).length||(d.evid||[]).length).length,tr:S.docs.filter(d=>(d.hist||[]).length).length}}
